        public IEnumerable<SMACustomerInfo> GetSMACustomerInfo(ICriteria criteria)
        {
            using (var db = new ObjectDb(criteria.GetSettingKey()))
            {
                using (var reader = db.ExecuteReader(criteria.GetSpParams()))
                {
                    while (reader.Read())
                    {
                        var custId = reader["custid"];

                        yield return custId == null || custId == DBNull.Value
                            ? new SMACustomerInfo(0, null, Convert.ToByte(reader["roleid"]))
                            : new SMACustomerInfo(Convert.ToInt32(custId), reader["username"].ToString(), Convert.ToByte(reader["roleid"]));
                    }
                }
            }
        }

